"use client";

import { Canvas } from "@react-three/fiber";
import { useEffect, useRef, useState, useSyncExternalStore } from "react";
import type { ReactNode, RefObject } from "react";
import { NeutralToneMapping } from "three";

import { cn } from "@/lib/utils";
import { agentRoleLabels } from "@/registry/ivan/components/agent/types";
import type {
  AgentAction,
  AgentRole,
} from "@/registry/ivan/components/agent/types";
import type { AgentMotion } from "@/registry/ivan/components/agent/use-agent-rig";
import { usePrefersReducedMotion } from "@/registry/ivan/hooks/use-prefers-reduced-motion";

import { AgentPoster } from "./agent-poster";
import { AgentStageScene } from "./agent-stage-scene";

export interface AgentStageProps {
  role: AgentRole;
  action?: AgentAction;
  focused?: boolean;
  motion?: AgentMotion;
  shadow?: boolean;
  label?: string;
  fallback?: ReactNode;
  className?: string;
}

let cachedWebGLSupport: boolean | null = null;

const detectWebGL = () => {
  if (cachedWebGLSupport !== null) {
    return cachedWebGLSupport;
  }
  try {
    const probe = document.createElement("canvas");
    const context = probe.getContext("webgl2") ?? probe.getContext("webgl");
    context?.getExtension("WEBGL_lose_context")?.loseContext();
    cachedWebGLSupport = context !== null;
  } catch {
    cachedWebGLSupport = false;
  }
  return cachedWebGLSupport;
};

const subscribeToPageShow = (onChange: () => void) => {
  window.addEventListener("pageshow", onChange);
  return () => window.removeEventListener("pageshow", onChange);
};

const getServerWebGLSupport = () => true;

const useWebGLSupport = () =>
  useSyncExternalStore(subscribeToPageShow, detectWebGL, getServerWebGLSupport);

const useIsInView = (target: RefObject<Element | null>) => {
  const [isInView, setIsInView] = useState(false);

  useEffect(() => {
    const element = target.current;
    if (!element) {
      return;
    }
    const observer = new IntersectionObserver(
      ([entry]) => setIsInView(entry?.isIntersecting ?? false),
      { rootMargin: "10% 0px" }
    );
    observer.observe(element);
    return () => observer.disconnect();
  }, [target]);

  return isInView;
};

export const AgentStage = ({
  role,
  action,
  focused,
  motion,
  shadow,
  label,
  fallback,
  className,
}: AgentStageProps) => {
  const frame = useRef<HTMLElement>(null);
  const [isHovered, setIsHovered] = useState(false);
  const hasWebGL = useWebGLSupport();
  const isInView = useIsInView(frame);
  const prefersReducedMotion = usePrefersReducedMotion();
  const resolvedMotion = motion ?? (prefersReducedMotion ? "reduced" : "full");

  let frameloop: "always" | "demand" | "never" = "never";
  if (isInView) {
    frameloop = resolvedMotion === "reduced" ? "demand" : "always";
  }

  return (
    <figure
      aria-label={label ?? agentRoleLabels[role]}
      className={cn("relative m-0 aspect-4/3 w-full", className)}
      onPointerEnter={() => setIsHovered(true)}
      onPointerLeave={() => setIsHovered(false)}
      ref={frame}
    >
      {hasWebGL ? (
        <Canvas
          dpr={[1, 2]}
          frameloop={frameloop}
          gl={{
            alpha: true,
            antialias: true,
            powerPreference: "high-performance",
            toneMapping: NeutralToneMapping,
          }}
        >
          <AgentStageScene
            action={action}
            focused={focused ?? isHovered}
            motion={resolvedMotion}
            role={role}
            shadow={shadow}
          />
        </Canvas>
      ) : (
        (fallback ?? <AgentPoster className="size-full" role={role} />)
      )}
    </figure>
  );
};

"use client";

import { PerspectiveCamera } from "@react-three/drei";
import { useThree } from "@react-three/fiber";
import { useEffect, useLayoutEffect } from "react";
import { MathUtils, Vector3 } from "three";

import { Agent } from "@/registry/ivan/components/agent/agent";
import type {
  AgentAction,
  AgentRole,
} from "@/registry/ivan/components/agent/types";
import { agentSignatureActions } from "@/registry/ivan/components/agent/types";
import type { AgentMotion } from "@/registry/ivan/components/agent/use-agent-rig";

import { StageLights } from "./stage-lights";

export interface AgentStageSceneProps {
  role: AgentRole;
  action?: AgentAction;
  focused?: boolean;
  motion?: AgentMotion;
  shadow?: boolean;
}

const lookTarget = new Vector3(0, 1, 0);
const viewDirection = new Vector3();
const elevation = 0.2;
const framedHeight = 2.5;
const framedWidth = 3;
const framePadding = 1.08;
const agentYaw = -0.28;

const FitCamera = () => {
  const camera = useThree((state) => state.camera);
  const aspect = useThree((state) => state.size.width / state.size.height);

  useLayoutEffect(() => {
    if (!("fov" in camera)) {
      return;
    }
    viewDirection.set(0, Math.sin(elevation), Math.cos(elevation));
    const halfFov = MathUtils.degToRad(camera.fov / 2);
    const fitHeight = framedHeight / 2 / Math.tan(halfFov);
    const fitWidth = framedWidth / 2 / (Math.tan(halfFov) * aspect);
    const distance = Math.max(fitHeight, fitWidth) * framePadding;
    camera.position.copy(lookTarget).addScaledVector(viewDirection, distance);
    camera.lookAt(lookTarget);
    camera.updateProjectionMatrix();
  }, [aspect, camera]);

  return null;
};

const FrameInvalidator = () => {
  const invalidate = useThree((state) => state.invalidate);
  const frameloop = useThree((state) => state.frameloop);

  useEffect(() => {
    if (frameloop === "demand") {
      invalidate();
    }
  }, [frameloop, invalidate]);

  return null;
};

export const AgentStageScene = ({
  role,
  action = agentSignatureActions[role],
  focused = false,
  motion,
  shadow = true,
}: AgentStageSceneProps) => (
  <>
    <PerspectiveCamera fov={30} makeDefault position={[0, 2.4, 10]} />
    <FitCamera />
    <StageLights />
    <FrameInvalidator />
    <Agent
      action={action}
      focused={focused}
      motion={motion}
      role={role}
      rotation-y={agentYaw}
      shadow={shadow}
    />
  </>
);

"use client";

import { Environment } from "@react-three/drei";
import { useThree } from "@react-three/fiber";
import { useMemo } from "react";
import type { Texture, WebGLRenderer } from "three";
import { PMREMGenerator } from "three";
import { RoomEnvironment } from "three/addons/environments/RoomEnvironment.js";

const environmentIntensity = 0.38;

const environments = new WeakMap<WebGLRenderer, Texture>();

const roomEnvironment = (gl: WebGLRenderer) => {
  const cached = environments.get(gl);
  if (cached) {
    return cached;
  }
  const generator = new PMREMGenerator(gl);
  const room = new RoomEnvironment();
  const { texture } = generator.fromScene(room, 0.04);
  room.dispose();
  generator.dispose();
  environments.set(gl, texture);
  return texture;
};

export const StageLights = () => {
  const gl = useThree((state) => state.gl);
  const environment = useMemo(() => roomEnvironment(gl), [gl]);

  return (
    <>
      <Environment
        environmentIntensity={environmentIntensity}
        map={environment}
      />
      <hemisphereLight args={["#fffaf3", "#cfc8bd", 1.25]} />
      <directionalLight
        color="#fff3e6"
        intensity={2.1}
        position={[-3.5, 6, 6]}
      />
      <directionalLight
        color="#e8eef7"
        intensity={0.7}
        position={[5, 2.5, 3]}
      />
      <directionalLight color="#ffffff" intensity={0.9} position={[2, 4, -6]} />
    </>
  );
};
